/** Developer docs are synced once from the current version and never versioned. */
export const UNVERSIONED_PREFIX = 'dev';

const isUnversioned = (slug) => slug === UNVERSIONED_PREFIX || slug.startsWith(`${UNVERSIONED_PREFIX}/`);

/** True when `slug` has a page under `docsDir` (src/content/docs or a version directory in it). */
export function docExists(docsDir, slug) {
  return ['.md', '/index.md'].some((ext) => existsSync(join(docsDir, `${slug}${ext}`)));
}

/** The sidebar with every item whose page `exists` rejects removed, and groups left empty dropped. */
export function presentSidebar(items, exists) {
  return items.flatMap((item) => {
    if (item.items) {
      const kept = presentSidebar(item.items, exists);
      return kept.length ? [{ ...item, items: kept }] : [];
    }
    return !item.slug || exists(item.slug) ? [item] : [];
  });
}

/** Every slug in a sidebar, depth first. */
export function sidebarSlugs(items) {
  return items.flatMap((item) => (item.items ? sidebarSlugs(item.items) : item.slug ? [item.slug] : []));
}

/**
 * starlight-versions' src/content/versions/<slug>.json for a version synced to
 * <docsRoot>/<slug>/: its own pages, plus the unversioned developer docs as
 * excluded slugs, which the plugin links to their single copy at the root.
 */
export function versionConfig(docsRoot, slug, sidebar = SIDEBAR) {
  const exists = (s) => docExists(isUnversioned(s) ? docsRoot : join(docsRoot, slug), s);
  const present = presentSidebar(sidebar, exists);
  return { sidebar: present, excluded: sidebarSlugs(present).filter(isUnversioned) };
}

export function writeVersionConfig(srcDir, slug) {
  const dir = join(srcDir, 'content', 'versions');
  mkdirSync(dir, { recursive: true });
  const config = versionConfig(join(srcDir, 'content', 'docs'), slug);
  writeFileSync(join(dir, `${slug}.json`), JSON.stringify(config, null, 2) + '\n');
}
